import{z as i,x as n,o as A,c as F,q as r,j as t,D as B,d as l,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"失败模式清单","description":"","frontmatter":{"title":"失败模式清单","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rlsys-failure-catalog.md","filePath":"llm/rlsys-failure-catalog.md","lastUpdated":1791063341000}'),D={name:"llm/rlsys-failure-catalog.md"};function d(p,E,C,m,f,u){const e=n("Mermaid");return A(),F("div",null,[E[2]||(E[2]=r('<h1 id="失败模式清单" tabindex="-1">失败模式清单 <a class="header-anchor" href="#失败模式清单" aria-label="Permalink to &quot;失败模式清单&quot;">​</a></h1><div class="epigraph"><p>RL 系统的失败分两种：会崩的与不会崩的。后者 loss 照降、奖励照涨，等你发现时账单已经出完。</p><footer>—— 据 verl、OpenRLHF 等开源框架的公开 issue 与运维记录整理</footer></div><p><a href="/llm/rlsys-cost-vs-sft">上一课</a>把账算清，本课把「钱怎么白烧的」编成目录，每条按症状、根因、探测、处置四列登记。前面各课已零散处理过这些失败（静默离策略、黑客、空转），本课把残件收进一本能照着巡检的册子——它也是生产事故复盘的输入格式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RL 训练的失败大多不抛异常。权重漏同步时，训练继续、曲线照涨，只是学到的与你以为的不是同一个策略；行为 logprob 错列时，重要性权重悄悄失真；评测题混进训练池时，守门人先被收买。这些失败的共同结构是「不变量被破坏而仪表不报」。所以清单不该按组件组织（引擎、RM、训练器），该按不变量组织——每条失败是某个不变量的一种破坏方式，每条探测是对应的一根断言。</p><p><span class="marginnote">「不变量」翻译成大白话：无论代码怎么改、负载怎么变，都必须恒成立的性质。「训练用的是第 \\(k\\) 版权重」就是一条不变量——它一旦被悄悄破坏（生成端其实拿着 \\(k-1\\) 版），不会报错，只会让更新方向悄悄变错。巡检，就是给每条不变量配一个自动提问：「它现在还成立吗？」</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按五条不变量列类。版本对齐类：权重漏同步（LoRA 合并漏层、MoE 专家漏更新）、训练与生成的对话模板漂移、行为 logprob 错列——探测用 logprob 探针与版本账本（<a href="/llm/rollout-weight-sync">rollout 引擎与权重同步</a>）。分布对齐类：零方差组占比飙升（白采）、长度分布漂移、熵坍缩、KL 失控——探测用批统计与漂移告警，处置靠动态采样与过滤（<a href="/llm/dynamic-sampling-rl">动态采样</a>、<a href="/llm/overlong-filtering">过长过滤</a>）。预算对齐类：长响应峰值把 KV 顶爆（按均值而非峰值预留）、上下文吃满（观测截断缺失）、检查点磁盘写满——探测用限额与水位告警。数值类：奖励归一化的 running 统计被离群奖励炸掉，后续批次优势尺度全歪（<a href="/llm/reward-whitening">奖励归一化与白化</a>）、梯度爆发、低精度下溢——探测用直方图与梯度范数。卫生类：评测题泄漏进训练池、金标流程被污染、提示与训练集重复——探测用哈希去重与单向闸门登记。</p><p><span class="marginnote">数字实例看「按均值预留」的坑：KV 缓存按 token 线性增长，一个 32 层、\\(d=4096\\) 的模型在 fp16 下每 token 约占 0.5 MB。响应均值 2000 token 时每条序列约 1 GB，看似宽裕；某一批冒出几条 16000 token 的长尾，单序列逼近 8 GB，几条同批就顶爆显存——预算按峰值预留，均值只用来算吞吐。</span></p><p><span class="marginnote">清单的使用方式是巡检不是救火：每类不变量配一条便宜的常态断言（探针、哈希、水位）。事故发生时按「哪个不变量最先失守」回溯，比按「最近改了什么代码」回溯快得多。</span></p>',10)),(A(),t(s,null,{default:B(()=>[o(e,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E4%BA%94%E6%9D%A1%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20--%3E%20V%5B%22%E7%89%88%E6%9C%AC%E5%AF%B9%E9%BD%90%EF%BC%9A%E6%9D%83%E9%87%8D%2F%E6%A8%A1%E6%9D%BF%2Flogprob%22%5D%0A%20%20INV%20--%3E%20D%5B%22%E5%88%86%E5%B8%83%E5%AF%B9%E9%BD%90%EF%BC%9A%E7%BB%84%E6%96%B9%E5%B7%AE%2F%E9%95%BF%E5%BA%A6%2F%E7%86%B5%2FKL%22%5D%0A%20%20INV%20--%3E%20B%5B%22%E9%A2%84%E7%AE%97%E5%AF%B9%E9%BD%90%EF%BC%9A%E6%98%BE%E5%AD%98%2F%E4%B8%8A%E4%B8%8B%E6%96%87%2F%E7%A3%81%E7%9B%98%22%5D%0A%20%20INV%20--%3E%20N%5B%22%E6%95%B0%E5%80%BC%E5%81%A5%E5%BA%B7%EF%BC%9A%E5%BD%92%E4%B8%80%E5%8C%96%2F%E6%A2%AF%E5%BA%A6%2F%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20INV%20--%3E%20H%5B%22%E5%8D%AB%E7%94%9F%EF%BC%9A%E8%AF%84%E6%B5%8B%E9%9A%94%E7%A6%BB%2F%E5%8E%BB%E9%87%8D%22%5D%0A%20%20V%20--%3E%20P1%5B%22%E6%96%AD%E8%A8%80%EF%BC%9A%E6%8E%A2%E9%92%88%E9%87%8D%E7%AE%97%20%2B%20%E7%89%88%E6%9C%AC%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20D%20--%3E%20P2%5B%22%E5%91%8A%E8%AD%A6%EF%BC%9A%E6%89%B9%E7%BB%9F%E8%AE%A1%E6%BC%82%E7%A7%BB%22%5D%0A%20%20B%20--%3E%20P3%5B%22%E6%B0%B4%E4%BD%8D%E4%B8%8E%E9%99%90%E9%A2%9D%22%5D%0A%20%20N%20--%3E%20P4%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%20%2B%20%E6%A2%AF%E5%BA%A6%E8%8C%83%E6%95%B0%22%5D%0A%20%20H%20--%3E%20P5%5B%22%E5%93%88%E5%B8%8C%E5%8E%BB%E9%87%8D%20%2B%20%E5%8D%95%E5%90%91%E9%97%B8%E9%97%A8%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"清单背后的机制认识是「响亮错误便宜，静默错误昂贵」。崩溃（显存、NaN）当步即知，损失是一次重启；静默错误（漏同步、污染、统计炸掉）以正确性的名义继续烧卡几周，损失不可逆。工程投资的重心因此按期望损失排：给静默失败配断言，比给响亮失败配自动重试更有价值。清单还有一个机制用途：新系统上线——换框架、换并行布局、换推理引擎——把五类不变量的断言当验收测试跑一遍，迁移事故几乎全部落在这五类里。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易以为「报错多说明系统不稳定」，实际上崩溃是最便宜的错误——一次重启就恢复；真正昂贵的是不报错的失败。权重漏同步后训练可以照常跑一周，烧掉的卡时和污染的检查点都无法回收。闹钟不响，不等于没事。")],-1)),(A(),t(s,null,{default:B(()=>[o(e,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%22%E4%B8%80%E6%AC%A1%E5%A4%B1%E8%B4%A5%E5%8F%91%E7%94%9F%22%5D%20--%3E%20Q%7B%22%E4%BB%AA%E8%A1%A8%E6%98%AF%E5%90%A6%E6%8A%A5%E8%AD%A6%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E5%93%8D%E4%BA%AE%E9%94%99%E8%AF%AF%22%7C%20C%5B%22%E5%BD%93%E6%AD%A5%E5%8D%B3%E7%9F%A5%EF%BC%9AOOM%20%2F%20NaN%20%2F%20%E6%A2%AF%E5%BA%A6%E7%88%86%E5%8F%91%22%5D%0A%20%20C%20--%3E%20R%5B%22%E9%87%8D%E5%90%AF%E6%88%96%E5%9B%9E%E6%BB%9A%EF%BC%8C%E6%8D%9F%E5%A4%B1%20%3D%20%E4%B8%80%E6%AC%A1%E9%87%8D%E5%90%AF%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E9%9D%99%E9%BB%98%E9%94%99%E8%AF%AF%22%7C%20S%5B%22%E8%AE%AD%E7%BB%83%E7%85%A7%E5%B8%B8%EF%BC%9Aloss%20%E7%85%A7%E9%99%8D%E3%80%81%E5%A5%96%E5%8A%B1%E7%85%A7%E6%B6%A8%22%5D%0A%20%20S%20--%3E%20W%5B%22%E6%95%B0%E5%91%A8%E5%90%8E%E5%8F%91%E7%8E%B0%EF%BC%9A%E5%8D%A1%E6%97%B6%E4%B8%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E4%B8%8D%E5%8F%AF%E9%80%86%22%5D%0A%20%20W%20--%3E%20A%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9A%E7%BB%99%E4%B8%8D%E5%8F%98%E9%87%8F%E9%85%8D%E5%B8%B8%E6%80%81%E6%96%AD%E8%A8%80%EF%BC%88%E6%8E%A2%E9%92%88%20%2F%20%E5%93%88%E5%B8%8C%20%2F%20%E6%B0%B4%E4%BD%8D%EF%BC%89%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>清单覆盖系统层失败，不覆盖算法层失败（发散、奖励设计错误、任务不可学）——后者表现为「一切正常但学不到东西」，靠评测与消融诊断。断言有覆盖与开销的权衡，抽样断言有漏报尾部，最终仍需金标评测兜底。清单是活的文档：每起事故回填新条目，否则它只是昨天的失败史。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>失败按不变量组织：版本、分布、预算、数值、卫生五类，每类配一条常态断言。</li><li>静默错误是主要期望损失：探针、哈希、水位比自动重试更值得投资。</li><li>长尾长度与离群奖励分别炸显存与归一化统计：按峰值预留、按直方图监控。</li><li>换框架、布局或引擎时把清单当验收测试跑；事故后回填条目保持清单活着。</li><li>出处：据 verl、OpenRLHF、slime 等开源框架的公开 issue 与运维实践整理。</li></ul>',4))])}const g=i(D,[["render",d]]);export{c as __pageData,g as default};
